INSERT INTO `Course` (`id`, `title`, `description`, `thumbnail`, `category`, `tags`, `price`, `instructorId`, `createdAt`, `updatedAt`, `hours`) VALUES
('24d68781-3739-4b4c-94e2-bf080683052d', 'Patients Right', '', '/uploads/thumbnails/1774053974513-528933945.jpg', 'Nursing', NULL, 0, '150955cc-f53b-4ea6-b77e-c363aabd9e5e', '2026-03-21 00:46:21.825', '2026-03-21 00:47:21.908', 0),
('469315df-6d9f-4624-9ac1-aac49996ee07', 'Fall Prevention', 'Falls are one of the most common and serious safety problems affecting older adults today. In\nhealthcare facilities such as nursing homes, assisted living centers, and hospitals, falls\nrepresent a major cause of injury, disability, and even death. Because of this, understanding fall\nprevention is extremely important for healthcare workers, caregivers, and anyone who works\nwith elderly individuals.\nAs people age, their bodies naturally go through many changes. Muscles may become weaker,\nbones become more fragile, and balance may not be as stable as it once was. In addition to\nthese physical changes, older adults may also experience medical conditions or take\nmedications that affect their coordination, strength, or alertness. When these factors combine\nwith environmental hazards—such as poor lighting, cluttered floors, or slippery surfaces—the\nrisk of falling increases significantly.\n', '/uploads/thumbnails/1773969397197-360027712.jpg', 'Nursing', NULL, 0, '150955cc-f53b-4ea6-b77e-c363aabd9e5e', '2026-03-20 01:16:59.030', '2026-03-20 01:16:59.030', 0),
('542c8094-5bb1-44a6-895b-8bf04dd28b90', 'Grooming Patients and Residents', '', '/uploads/thumbnails/1773999825549-33870989.jpg', 'Nursing', NULL, 0, '150955cc-f53b-4ea6-b77e-c363aabd9e5e', '2026-03-20 09:43:52.954', '2026-03-20 09:43:52.954', 0),
('6474ac90-2ccb-48a7-a08d-e98d8455bf66', 'Patient and Resident’s Safety', '', '/uploads/thumbnails/1774279160545-846977026.jpg', 'Nursing', NULL, 0, '150955cc-f53b-4ea6-b77e-c363aabd9e5e', '2026-03-23 15:19:24.967', '2026-03-23 15:19:24.967', 0),
('7b28c015-3fe9-44d1-9626-c56c1743b0dd', 'Vital Signs and Weights', '', '/uploads/thumbnails/1774285743655-267560671.jpg', 'Nursing', NULL, 0, '150955cc-f53b-4ea6-b77e-c363aabd9e5e', '2026-03-23 17:09:07.083', '2026-03-23 17:09:07.083', 0),
('829bf6cd-1ffd-41fa-83ad-aef508d0416d', 'Ethics and Legal Ethics', '', '/uploads/thumbnails/1774047737154-814510393.jpg', 'Nursing', NULL, 0, '150955cc-f53b-4ea6-b77e-c363aabd9e5e', '2026-03-20 23:02:34.066', '2026-03-20 23:02:34.066', 0),
('89f378d8-36d0-451e-bea3-fe236556b77a', 'Caring for People with Dementia', '', '/uploads/thumbnails/1773966129378-294190613.jpg', 'Nursing', NULL, 0, '150955cc-f53b-4ea6-b77e-c363aabd9e5e', '2026-03-20 00:22:12.162', '2026-03-20 00:22:12.162', 0),
('8b2c6fd8-c88c-4167-a133-924c5decdcc9', 'Nutrition and Fluids', '', '/uploads/thumbnails/1774051467591-215765946.jpg', 'Nursing', NULL, 0, '150955cc-f53b-4ea6-b77e-c363aabd9e5e', '2026-03-21 00:04:59.472', '2026-03-21 00:04:59.472', 0),
('9eb9ef31-e267-486a-b9e7-210580c4b7f9', 'Infection Control', '', '/uploads/thumbnails/1774036650440-637348840.jpg', 'Nursing', NULL, 0, '150955cc-f53b-4ea6-b77e-c363aabd9e5e', '2026-03-20 19:57:41.191', '2026-03-20 19:57:41.191', 0),
('b2342850-aa5d-49f2-959e-b78321a4b40b', 'Death and Dying ', 'Death can occur suddenly without notice or it can be expected. Older people, or people with\nterminal illnesses, may have time to prepare for death. Preparing for death is a process. It\naffects the person’s emotions and behavior.\nDr. Elizabeth Kubler-Ross studied and wrote about the grief process. Her book On Death and\nDying describes five stages of dying that people and their loved ones may reach before death.\nNot all residents go through all the stages. Some people may stay in one stage until death. They\nmay move back and forth between the stages during the process.', '/uploads/thumbnails/1773960223021-558834385.jpg', 'Nursing', NULL, 0, '150955cc-f53b-4ea6-b77e-c363aabd9e5e', '2026-03-19 22:43:48.043', '2026-03-19 22:43:48.043', 0),
('b6b62f41-35c2-4e78-95b2-be43f127cc27', 'HIPAA', '', '/uploads/thumbnails/1774011041806-489650534.jpg', 'Nursing', NULL, 0, '150955cc-f53b-4ea6-b77e-c363aabd9e5e', '2026-03-20 12:51:30.016', '2026-03-20 12:51:30.016', 0),
('b7d36c48-532b-4ce7-9a61-9227e1f58d11', 'Positioning and Lifting Patients', '', '/uploads/thumbnails/1774090344851-562399793.jpg', 'Nursing', NULL, 0, '150955cc-f53b-4ea6-b77e-c363aabd9e5e', '2026-03-21 10:52:33.267', '2026-03-21 10:52:33.267', 0),
('b8509a51-3b06-47a3-8509-e2c21930bd0e', 'Assisting with Urinary and Bowel Elimination', 'Elimination of waste from the body is a basic human need. Just as the body requires\noxygen, nutrition, and rest to survive, it must also remove waste products to maintain\ninternal balance. When waste is not properly eliminated, toxins can build up, leading to\ninfection, discomfort, organ dysfunction, and serious medical complications.', '/uploads/thumbnails/1773922906643-199760615.jpg', 'Nursing', NULL, 0, '150955cc-f53b-4ea6-b77e-c363aabd9e5e', '2026-03-19 12:22:26.218', '2026-03-19 12:22:26.218', 0),
('bac90a7a-5b48-4ab4-af88-c9e7f4b77152', 'Transferring Patients and Residents', '', '/uploads/thumbnails/1774284639283-577509924.jpg', 'Nursing', NULL, 0, '150955cc-f53b-4ea6-b77e-c363aabd9e5e', '2026-03-23 16:50:43.018', '2026-03-23 16:50:43.018', 0),
('bc4d0116-8ba8-40e3-87a0-c70eabeaa6a9', 'Foundations of Communication', 'People communicate in several different ways. Communication does not only involve speaking\nwords. It can also occur through drawings, pictures, signs, and symbols. For example, traffic\nsigns communicate rules to drivers without the use of spoken words. In the same way, a\nperson’s behavior can also communicate a message. The way a person acts, stands, or reacts\nto a situation can tell others how they feel or what they think. Because of this, communication\nincludes both spoken messages and messages that are expressed through actions or physical\nsignals', '/uploads/thumbnails/1773941805275-60032604.jpg', 'Nursing', NULL, 0, '150955cc-f53b-4ea6-b77e-c363aabd9e5e', '2026-03-19 17:36:50.066', '2026-03-19 17:36:50.066', 0),
('e93ed028-bef9-4e5d-8f32-57e884757e84', 'Stress and Stress Management', '', '/uploads/thumbnails/1774283069556-463066561.jpg', 'Nursing', NULL, 0, '150955cc-f53b-4ea6-b77e-c363aabd9e5e', '2026-03-23 16:24:32.957', '2026-03-23 16:24:32.957', 0),
('f827a1af-2835-438e-8b60-142533f83048', 'Cleanliness and Hygiene', 'Cleanliness and hygiene refer to the practices that individuals follow to maintain their bodies\nand environments in a clean and healthy condition. These practices include bathing, brushing\nteeth, washing hands, wearing clean clothes, and keeping living spaces clean and organized.\nMaintaining cleanliness is not simply about appearance; it is primarily about protecting health\nand preventing disease.\nIn healthcare settings such as hospitals, clinics, or nursing homes, hygiene becomes even more\nimportant because patients may already be vulnerable due to illness or injury. A lack of proper\nhygiene can lead to infections that may worsen a patient’s condition or delay recovery.', '/uploads/thumbnails/1773928033876-197594166.jpg', 'Nursing', NULL, 0, '150955cc-f53b-4ea6-b77e-c363aabd9e5e', '2026-03-19 13:47:38.331', '2026-03-19 13:47:38.331', 0);
