INSERT INTO `Lesson` (`id`, `title`, `description`, `videoUrl`, `materialUrl`, `order`, `moduleId`, `createdAt`) VALUES
('0031c265-06fb-4a54-9618-626a5e6da762', 'Caring for a Dying Person', 'Caring for a dying person is one of the most sensitive and meaningful responsibilities in\nhealthcare. When an individual is approaching the end of life, the primary goal of care shifts\nfrom curing illness to providing comfort, dignity, and emotional support. This type of care is\noften referred to as palliative care, which focuses on improving the quality of life for people who\nare facing serious or terminal illness.', '/uploads/videos/1773962782694-181301776.mp4', '/uploads/materials/1773961744731-878998934.pdf', 1, '6c66106f-f05e-4786-ab44-409ccf51a855', '2026-03-19 23:27:35.492'),
('0b980e00-f7ae-4583-867e-c840c93032ba', 'Introduction to Stress', 'Stress is a common part of everyday life and affects every individual at different times. In simple\nterms, stress is the state of being frightened, excited, confused, in danger, or irritated. It is a\nreaction that occurs when people face situations that challenge their ability to cope or adapt.\nStress can arise from both negative and positive experiences, and it influences how people\nthink, feel, and behave. Understanding stress is extremely important, particularly in healthcare\nprofessions where workers must manage demanding environments while also providing care to\nothers.', '/uploads/videos/1774283722334-89547596.mp4', '/uploads/materials/1774283136585-976392690.pdf', 1, '9100fc0e-264c-4f8f-8483-e231a5598ae1', '2026-03-23 16:45:14.126'),
('0d9a0881-e63b-446d-8658-a1f92f781cc0', 'Guidelines for Caring for a Dying Resident', '', '/uploads/videos/1773964215293-929606738.mp4', '/uploads/materials/1773963683576-308033313.pdf', 1, '705105ea-841a-41ce-82cd-711c91029cc1', '2026-03-19 23:51:16.020'),
('13cf5320-9ec7-444c-9643-72459076ab37', 'Common Patient Positions and Their Purposes', 'In healthcare settings, patients are often placed in specific positions to improve comfort, support\ntreatment, and prevent complications. Proper positioning helps maintain body alignment, reduce\npressure on certain areas of the body, and promote normal body functions such as breathing\nand circulation.\nCaregivers must understand the different positions used in patient care and know when each\nposition is appropriate. Correct positioning also helps prevent complications related to\nimmobility, such as pressure ulcers, muscle stiffness, and breathing problems', '/uploads/videos/1774278393261-801355639.mp4', '/uploads/materials/1774277800541-556767568.pdf', 1, '3ac858c2-ceae-49ef-995c-b2132eeaaf24', '2026-03-23 15:16:16.258'),
('14c6bdc2-a4f8-4db2-a49e-24b982ec92a5', 'Foundations of Patient Rights and Participation in Healthcare', '', '/uploads/videos/1774054111149-953655482.mp4', '/uploads/materials/1774054076530-446914536.pdf', 1, '8ff86c7b-31b4-471c-8db2-01ae7a7ab909', '2026-03-21 00:49:38.492'),
('14e3ec18-47fa-4069-802d-5169fc949dd8', ' Complications of Immobility', 'When patients are unable to move or change their position for long periods of time, their bodies\ncan begin to develop serious health problems. This condition is known as immobility, and it can\naffect nearly every system in the body. Many patients in hospitals, nursing homes, or\nrehabilitation centers may experience limited mobility because of illness, surgery, injury, or\nweakness. Because of this, healthcare workers must understand the complications that\nimmobility can cause and take steps to prevent them.', '/uploads/videos/1774093539686-551304427.mp4', '/uploads/materials/1774093822863-184013430.pdf', 1, 'f8d60859-e30a-41da-b80c-8f608cfe9c62', '2026-03-21 11:50:26.293'),
('16a26c5e-22f0-4b1a-aba5-ed32beb36698', 'Providing Oral Care', 'Oral care involves cleaning the mouth, teeth, gums, and tongue. Maintaining oral hygiene is\nessential because the mouth contains many bacteria that can cause infections if not properly\ncontrolled.', '/uploads/videos/1773929132138-239668487.mp4', '/uploads/materials/1773928657019-585439867.pdf', 1, 'f6baa31e-b320-40e3-a890-ae63a397852f', '2026-03-19 14:10:11.833'),
('188f05d3-48ef-4e73-bdba-61c86fe81e25', 'How to Care for a Person with Dementia', 'Caring for a person with dementia requires patience, compassion, and a clear understanding of\nhow the disease affects the individual. As dementia progresses, people gradually lose the ability\nto perform tasks they once managed easily. Activities such as bathing, dressing, eating, or using\nthe bathroom can become confusing and frustrating. Because of this, caregivers play an\nessential role in helping individuals maintain their dignity, comfort, and safety while assisting\nthem with daily activities.\n', '/uploads/videos/1773968329980-284893128.mp4', '/uploads/materials/1773968270015-186025910.pdf', 1, '9fe57443-4780-468c-bdeb-069b1d9020b4', '2026-03-20 01:00:06.188'),
('1d684c74-c784-46a6-b059-351a1e9a0da2', 'How to Assist with Bedpans', 'In some situations, residents are unable to get out of bed to use the bathroom. This may be due\nto weakness, paralysis, recent surgery, fall risk, fractures, severe illness, or medical restrictions.\nIn these cases, a bedpan is used to allow elimination while the resident remains in bed.\nWomen may use a bedpan for both urination and defecation.\nMen may use a bedpan for defecation and typically use a urinal for urination', '/uploads/videos/1773924777596-439408595.mp4', '/uploads/materials/1773924315034-191482420.pdf', 1, '70685a51-75c7-4cd4-b9ae-52610a277de4', '2026-03-19 12:53:42.324'),
('1eb1d932-5c0c-4ef0-813b-4176ae03ac39', 'When Death Occurs and Postmortem Care', '', '/uploads/videos/1773965968517-294589668.mp4', '/uploads/materials/1773965539107-732860945.pdf', 1, '1261f7df-b095-452f-87c2-f5a388d002dd', '2026-03-20 00:20:08.695'),
('1eb939fe-5ff8-44ac-a037-1428a52832e1', 'How to Care for a Person with an Indwelling Urinary Catheter', 'Some residents are unable to urinate using a toilet, bedpan, or urinal. In these situations, a\nurinary catheter may be inserted. An indwelling urinary catheter is a tube that is inserted into\nthe bladder and left in place to provide continuous urine drainage.', '/uploads/videos/1773925863446-172417416.mp4', '/uploads/materials/1773925365811-752021913.pdf', 1, 'a4b4121c-7568-4f33-b31d-984815208af0', '2026-03-19 13:16:13.139'),
('24c561de-733f-4f9a-95da-02ca5226a37f', 'Dignity, Respect, Privacy, and Independence in Patient Care', 'An essential part of patient rights in healthcare is the protection of a patient’s dignity, respect,\nprivacy, and independence. These principles ensure that individuals receiving medical care are\ntreated not only as patients but also as human beings with feelings, preferences, and personal\nidentities. Healthcare workers, especially nursing assistants and caregivers, play a crucial role in\nprotecting these rights during everyday interactions with patients.', '/uploads/videos/1774054933425-176676877.mp4', '/uploads/materials/1774054208496-786148943.pdf', 1, '6192cd4c-7986-4252-be4d-3bb3b5526afc', '2026-03-21 01:02:20.602'),
('24d73cbc-0b13-484d-973e-8331d8780291', 'How to Assist a Man with a Urinal', 'Male residents commonly use a urinal to void urine when they are unable to walk safely to the\nbathroom. ', '/uploads/videos/1773925221193-939389911.mp4', '/uploads/materials/1773924893899-226104316.pdf', 1, 'cb8ded44-c589-4731-9ff6-f3ca32e91014', '2026-03-19 13:01:49.886'),
('2e8dffcf-772f-47f1-9c8a-0bc3ca952f59', 'Introduction, Patient Empathy, and Preparation Before Positioning Patients', 'Positioning and lifting patients is an essential responsibility for nursing assistants and other\nhealthcare workers. Many patients are unable to move or change their positions on their own\nbecause of illness, injury, weakness, or medical treatment. In these situations, healthcare\nworkers must assist them in repositioning safely and comfortably. This task may appear simple,\nbut it is extremely important for protecting the patient’s health and preventing complications.\nUnderstanding the needs of patients and preparing properly before repositioning them are the\nfirst steps in providing quality care. Caregivers must always approach this task with empathy,\npatience, and careful planning.', '/uploads/videos/1774091813563-73813636.mp4', '/uploads/materials/1774091969147-148310964.pdf', 1, '2a62adf3-ba26-4f3a-b519-b772b89c7599', '2026-03-21 11:19:50.118'),
('302b113f-4905-4584-aac8-39576a29f551', ' Treatment and Management of Dementia', 'Although there is currently no cure for dementia, a wide range of treatment and management\nstrategies can significantly improve the quality of life for individuals living with the condition.\nEffective dementia care focuses on slowing symptom progression, maintaining cognitive\nfunction for as long as possible, managing behavioral and psychological symptoms, and\nsupporting both patients and caregivers. Treatment approaches typically involve a combination\nof medications, non-pharmacological interventions, lifestyle modifications, and strong social and\ncaregiver support systems.', '/uploads/videos/1773968639461-574985425.mp4', '/uploads/materials/1773968529695-551406254.pdf', 1, 'cedfd487-399a-4de6-a8e4-986eb7670566', '2026-03-20 01:04:27.019'),
('317f0649-0f7f-4d2b-bf20-7f4e6539156a', 'Introduction to Foundations of Communication', '', '/uploads/videos/1773944298789-321412326.mp4', '/uploads/materials/1773942555790-143065258.pdf', 1, '44a4373a-edbc-4dc2-8741-097ce16c57b7', '2026-03-19 18:19:48.556'),
('31d5c438-ee7b-4caa-b745-a4dc622ff025', 'Abuse', 'Abuse is a serious issue in healthcare settings, especially when caring for vulnerable individuals\nsuch as older adults, children, or people with disabilities. Healthcare professionals have a\nresponsibility to recognize, prevent, and report abuse whenever it occurs or is suspected.\nUnderstanding the different types of abuse and knowing how to respond appropriately is\nessential for maintaining a safe and respectful environment for patients and residents.', '/uploads/videos/1774050124447-822615976.mp4', '/uploads/materials/1774049599592-424567842.pdf', 1, '336d8deb-f4eb-400e-9c49-59f453aa8f5c', '2026-03-20 23:44:27.596'),
('346163e9-ad79-40c4-ac5c-36d626688100', 'Factors That Cause Falls and Guidelines for Prevention', '', '/uploads/videos/1773970141356-493734788.mp4', '/uploads/materials/1773970074136-858921590.pdf', 1, '84814514-effd-43c9-af12-b6860795ba9d', '2026-03-20 01:30:06.165'),
('3649440b-d047-4e3c-b980-e50ed6610979', 'Body Mechanics and Patient Assessment Before Transfer', 'When assisting patients or residents with movement, healthcare workers must understand two\ncritical concepts: body mechanics and patient assessment. These principles ensure that\ntransfers are performed safely, efficiently, and without causing injury to either the patient or the\ncaregiver. Because transferring patients is a task performed many times throughout the day in\nhealthcare environments, mastering these skills is essential for long-term safety and effective\npatient care.', '/uploads/videos/1774284918181-825064097.mp4', '/uploads/materials/1774284819112-504125435.pdf', 1, 'ccbb43ec-31ef-47ba-9f0f-c381621786ff', '2026-03-23 16:55:22.387'),
('36975f4a-ac4a-4a06-aa6c-30886bfd25c7', 'Introduction to Infection Control and Its Purpose', 'Infection control is one of the most important responsibilities in healthcare. Every healthcare\nworker, whether a nurse, doctor, nursing assistant, or home health aide, plays a role in\npreventing the spread of disease. When people enter healthcare facilities such as hospitals,\nnursing homes, clinics, or rehabilitation centers, they expect to receive care that will improve\ntheir health. However, if proper infection control measures are not followed, these facilities can\nbecome places where infections spread quickly. That is why infection control is a fundamental\npart of safe healthcare practice.', '/uploads/videos/1774036839415-621652836.mp4', '/uploads/materials/1774036732813-782735735.pdf', 1, '9b4f55ff-3b1c-4781-a40e-f0c97a0c0e54', '2026-03-20 20:00:44.654'),
('3bdbf252-0a46-4038-a9dd-a3fe153beb8a', 'Understanding and Monitoring Restraints', 'In healthcare environments, maintaining the safety of patients and residents sometimes requires\nthe use of special measures. One of these measures is the use of restraints. Restraints are\nused only when necessary to prevent individuals from harming themselves or others. Because\nrestraints can restrict a person\'s freedom and affect their well-being, they must always be used\ncarefully, ethically, and according to strict medical guidelines. Understanding what restraints are,\nwhen they are appropriate, and how they should be monitored is essential for healthcare\nworkers, especially nursing assistants who are often responsible for observing and caring for\nrestrained patients.', '/uploads/videos/1774280032932-22293182.mp4', '/uploads/materials/1774279380426-748836535.pdf', 1, '6722ee5b-8bd7-4edb-8ba4-125b62be29ba', '2026-03-23 15:42:06.675'),
('42d5237e-1fec-4057-852a-c6d539677547', 'Stages of Dementia', 'Dementia is a progressive condition, which means that the symptoms gradually worsen over\ntime. Although the rate of progression varies from person to person, dementia generally follows\na pattern of stages. Understanding these stages is extremely important for caregivers and\nhealthcare professionals because the needs of the person change significantly as the disease\nadvances. By recognizing the stage of dementia that a person is experiencing, caregivers can\nbetter anticipate challenges and provide the appropriate level of care and support.', '/uploads/videos/1773966865363-314201679.mp4', '/uploads/materials/1773966334544-570982609.pdf', 1, '6cbcdb66-7df9-4a10-95d4-eb60469bc6d1', '2026-03-20 00:34:34.349'),
('46f9935c-2fb4-479e-9415-8dc9f5dbdf55', 'How to Measure Urine Output, Incontinence, and Ostomy Care', 'In many facilities, urine drainage bags are routinely emptied and the urine measured at the end\nof each shift, unless ordered otherwise. The urine drainage bag should also be emptied\nwhenever it becomes full. This prevents backflow, leakage, discomfort, and reduces the risk of\ninfection.', '/uploads/videos/1773926761826-151988013.mp4', '/uploads/materials/1773926260781-883274560.pdf', 1, 'c90d84a8-2e58-4e41-b038-c8dbd3b755d7', '2026-03-19 13:35:34.342'),
('48fb42ed-4b81-45f2-a95e-d5329f2dac34', 'Measuring Height and Weight and Their Importance in Patient Care', 'Height and weight are important physical measurements used in healthcare to assess a\nperson’s overall health status. These measurements are not technically classified as vital signs\nlike temperature, pulse, respiration, or blood pressure, but they are still essential indicators of\nphysical condition and nutritional status. Healthcare workers measure height and weight\nregularly because changes in these values may reveal important information about a person’s\nhealth. They can indicate growth patterns, nutritional problems, fluid balance issues, or the\nprogression of certain diseases. Because of this, accurate measurement and proper\ndocumentation of height and weight are important responsibilities in patient care.', '/uploads/videos/1774352467350-607623091.mp4', '/uploads/materials/1774351935442-798644258.pdf', 1, '5e18be6c-2132-47af-9352-3ecc28e3ce99', '2026-03-24 11:43:39.252'),
('4fa5a62f-6eee-46ba-b708-48a8f0978127', 'Safety Equipment in Fall Prevention: Wheel Locks, Transfer Belts, and Bed Rails', 'Preventing falls in healthcare environments requires not only awareness and supervision but\nalso the correct use of safety equipment. Many injuries occur not because equipment is\nunavailable, but because it is not used properly or consistently. Three important safety tools\nused in fall prevention are wheel locks, transfer or gait belts, and bed rails. When caregivers\nunderstand how and when to use these tools correctly, they can significantly reduce the risk of\naccidents and improve patient safety.', '/uploads/videos/1773970309334-786895583.mp4', '/uploads/materials/1773970257902-133489195.pdf', 1, 'f02404fe-81f3-42ca-af7b-d89059f4eb1e', '2026-03-20 01:32:40.411'),
('5504d31e-50b3-4dad-8579-498668db24c6', 'Foundations of Patient and Resident Safety', 'Patient and resident safety is one of the most important responsibilities in any healthcare\nenvironment. Nursing assistants and other healthcare workers play a crucial role in ensuring\nthat patients remain protected from harm while receiving care. Safety is not simply about\nresponding to emergencies; it is about preventing hazards, preparing properly before performing\ntasks, and maintaining a safe environment at all times. By understanding the basic principles of\npatient and resident safety, healthcare workers can reduce risks, improve quality of care, and\nprotect both patients and staff members.', '/uploads/videos/1774279330663-902510912.mp4', '/uploads/materials/1774279210224-490304103.pdf', 1, 'c4a419af-f404-403a-accc-d24786495301', '2026-03-23 15:22:16.688'),
('554306bd-ab29-4d9b-8125-2889edf8459e', 'Fire Prevention and Fire Emergency Response', 'Fire emergencies are among the most dangerous situations that can occur in healthcare\nfacilities. Hospitals, nursing homes, and long-term care centers often house individuals who\nmay be ill, elderly, disabled, or unable to move independently. Because many patients cannot\nevacuate quickly without assistance, a fire can become extremely dangerous if not handled\nproperly. For this reason, healthcare workers must understand both how to prevent fires and\nhow to respond effectively if a fire occurs. Proper training, awareness, and quick action are\nessential for protecting patients, residents, staff members, and visitors.', '/uploads/videos/1774281750164-905673525.mp4', '/uploads/materials/1774281176440-88828816.pdf', 1, '6d3e4753-8046-4715-9f1b-71b7084be389', '2026-03-23 16:07:43.981'),
('59ea1592-3271-4386-9726-26f4e3ca0571', 'Introduction to Dementia', 'Dementia is one of the most challenging and complex conditions faced in modern healthcare. It\nis a disorder that affects the brain and gradually interferes with a person’s ability to think,\nremember, reason, and make decisions. While dementia primarily affects older adults, it is\nimportant to understand that it is not a normal part of aging. Instead, it is a medical condition\ncaused by damage to brain cells that interferes with the way the brain functions.\nThe effects of dementia extend far beyond the individual who is diagnosed with the condition. It\nalso has a profound emotional, physical, and psychological impact on family members,\ncaregivers, and healthcare professionals who provide care and support. Families often struggle\nto cope with the changes they see in their loved one. Over time, the person they once knew\nmay begin to change in personality, memory, and behavior. These changes can be difficult and\nsometimes heartbreaking for family members to witness.', '/uploads/videos/1773966247500-459492870.mp4', '/uploads/materials/1773966189403-684881411.pdf', 1, '09bf9c24-30c6-4ae6-8839-be4d8d389109', '2026-03-20 00:24:27.959'),
('5d312bdb-0010-4aa1-ac92-4fff9766bfa9', 'Medical Information, Refusing Treatment, Use of Restraints, and Practical Applications', 'Another critical aspect of patient rights focuses on access to medical information, the ability to\nrefuse treatment, and the safe and ethical use of restraints. These rights ensure that patients\nmaintain control over their healthcare decisions while also protecting their safety. Healthcare\nprofessionals, including certified nursing assistants (CNAs), must understand their\nresponsibilities in supporting these rights and responding appropriately in different situations.', '/uploads/videos/1774055619026-758282638.mp4', '/uploads/materials/1774054993980-533899561.pdf', 1, 'e7c7bf5e-029f-477f-85f9-7fada32724e8', '2026-03-21 01:13:52.225'),
('6c0a6775-eabc-4753-96fc-473d30bfa773', 'Medical Emergencies, Accident Response, and Final Safety Procedures', 'Healthcare environments are designed to promote healing and recovery, but emergencies can\noccur at any time. Patients and residents in hospitals or long-term care facilities often have\nmedical conditions that make them vulnerable to sudden health crises. Because of this,\nhealthcare workers must be prepared to recognize and respond quickly to medical emergencies\nand accidents. A nursing assistant’s ability to identify warning signs, take immediate action, and\nfollow emergency procedures can make the difference between life and death. In addition to\nresponding to emergencies, healthcare workers must also follow proper finishing procedures\nafter providing care to ensure continued patient safety and comfort.', '/uploads/videos/1774282613574-31135476.mp4', '/uploads/materials/1774282107102-679385586.pdf', 1, '5faaf07f-10b9-475a-abaf-85009871a135', '2026-03-23 16:17:44.829'),
('6d0b99bf-d33d-4c37-a1f0-0eaaef088268', 'Finishing Up Steps', 'When completing a procedure, always follow a routine to ensure the resident’s safety and\ncomfort. Start by confirming that the person is comfortable and properly aligned in bed or in a\nchair. Good body alignment supports circulation, prevents strain, and helps the resident feel\nsecure.', '/uploads/videos/1773927463474-503050576.mp4', '/uploads/materials/1773927388975-699406441.pdf', 2, 'c90d84a8-2e58-4e41-b038-c8dbd3b755d7', '2026-03-19 13:37:46.451'),
('6df7408d-4137-46b7-9d6d-011a388081dd', 'Cardiovascular Vital Signs   Pulse and Blood Pressure', 'Monitoring the cardiovascular system is a major part of assessing a patient’s health. Two of the\nmost important vital signs used to evaluate the cardiovascular system are pulse rate and blood\npressure. These measurements provide valuable information about how well the heart and\nblood vessels are functioning. Because the cardiovascular system is responsible for circulating\noxygen, nutrients, and other essential substances throughout the body, changes in pulse or\nblood pressure can indicate serious health problems. For healthcare workers, accurately\nmeasuring and interpreting these vital signs is an essential skill.', '/uploads/videos/1774343617936-670330321.mp4', '/uploads/materials/1774343097555-524520163.pdf', 1, '6a615ca5-9d10-4070-9446-e620c7dc10f3', '2026-03-24 09:13:44.661'),
('79ded1c4-923a-43ad-96cd-c9b2ed46413c', 'Foundations of Vital Signs and Temperature Measurement Basics', 'Understanding vital signs is one of the most fundamental responsibilities in healthcare. These\nmeasurements provide essential information about how well a person’s body is functioning.\nBecause vital signs reflect critical body processes such as circulation, breathing, and\ntemperature regulation, even small changes can indicate that something is wrong. For nursing\nassistants and other healthcare professionals, learning how to measure and interpret vital signs\naccurately is extremely important because these measurements are often the first indicators of a\nchange in a patient’s health condition.\n', '/uploads/videos/1774286651147-116031177.mp4', '/uploads/materials/1774285781988-342131496.pdf', 1, '27dec30e-b81b-4be7-a63e-d057ec137cb9', '2026-03-23 17:24:34.824'),
('7c694759-6efc-458e-ae94-3df0c413264f', ' Introduction to Grooming and Getting Ready', 'Personal grooming is an essential part of daily care for patients and residents in healthcare\nfacilities. Grooming includes activities such as bathing, hair care, shaving, dressing, and\nmaintaining clean hands, feet, and nails. These activities may seem simple, but they play a very\nimportant role in maintaining both the physical and emotional well-being of individuals receiving\ncare. For many patients and residents, especially those who are elderly, ill, or physically limited,\nassistance with grooming may be necessary to help them remain comfortable, healthy, and\nconfident.', '/uploads/videos/1774002240993-551812640.mp4', '/uploads/materials/1773999883610-407393323.pdf', 1, 'e42d2b00-03b9-4d39-a131-d1b33ca601f8', '2026-03-20 10:24:58.723'),
('84ff4005-6cc1-44be-833d-98e4b3b22df3', 'Breaking the Chain of Infection and Basic Practices of Infection Control', 'Breaking the chain of infection means removing or controlling one or more of the links that\nallow pathogens to spread. Each link in the chain—such as the pathogen, reservoir, portal of\nexit, method of transmission, portal of entry, or susceptible host—provides an opportunity for\nhealthcare workers to intervene. By carefully following infection control techniques, caregivers\ncan stop pathogens before they reach another person.', '/uploads/videos/1774042467461-806310569.mp4', '/uploads/materials/1774040474019-138498909.pdf', 1, '0e8d8cfa-016d-4dab-946d-6e5834f33b83', '2026-03-20 21:35:00.774'),
('8930c04f-d53c-404e-968a-1933c47403f0', 'Temperature Measurement Procedures (Oral, Rectal, and Alternative Methods)', 'Measuring body temperature is one of the most common and important tasks performed in\nhealthcare settings. Body temperature reflects the balance between heat produced by the body\nand heat lost to the environment. Because temperature is closely connected to metabolism,\ninfection, inflammation, and overall body function, changes in temperature can provide early\nwarning signs of illness or complications. For this reason, healthcare workers must understand\nnot only how to measure temperature but also when to use different measurement methods and\nhow to perform each technique safely and accurately.', '/uploads/videos/1774287347668-929442825.mp4', '/uploads/materials/1774286703413-449983504.pdf', 1, '6083a430-fe0b-4fa9-9289-0b0e1a67e2a2', '2026-03-23 17:36:07.691'),
('8aae6cdf-3ba4-4ba9-81f9-f1c55390a1a9', 'Signs That Stress Is Not Being Managed Properly', 'Stress is a normal part of life, but problems begin to occur when it is not managed effectively.\nWhen stress builds up over time and individuals do not have healthy ways to cope with it, it can\nbegin to affect their emotions, behavior, relationships, and job performance. Recognizing the\nsigns that stress is becoming overwhelming is extremely important, especially in healthcare\nenvironments where workers are responsible for the safety and well-being of others. Being able\nto identify these warning signs early allows individuals to take action before stress leads to\nserious consequences.', '/uploads/videos/1774284619093-406764869.mp4', '/uploads/materials/1774284478167-649257962.pdf', 1, '8387f2ff-104e-4032-8b8f-a99d6ea6b0b0', '2026-03-23 16:50:24.217'),
('8b9f19b6-2bc9-4481-a1d2-2f96cf991a08', 'Stages of Death', 'Death is a natural part of the human life cycle, yet it remains one of the most emotionally\ncomplex experiences for individuals and their families. Some deaths occur suddenly, such as\nthose resulting from accidents or unexpected medical events. Others occur gradually,\nparticularly in older adults or individuals suffering from terminal illnesses such as advanced\ncancer or severe chronic disease. When death is expected, individuals often go through a\npsychological and emotional process as they prepare for the end of life. Understanding this\nprocess is extremely important for caregivers, nurses, and healthcare assistants because it\nhelps them provide compassionate, respectful, and appropriate care.\n', '/uploads/videos/1773961647903-285365537.mp4', '/uploads/materials/1773960374945-891050065.pdf', 1, '44cabe37-89ae-48a9-ab6f-efec30c9c4f0', '2026-03-19 23:08:20.712'),
('8c2a41a4-7264-4c4d-bbcc-728e13022641', 'Guidelines: Legal and Ethical Behavior', 'Legal and ethical behavior is one of the most important foundations of professional healthcare\npractice. Healthcare workers are trusted with the responsibility of caring for vulnerable\nindividuals, including patients who may be ill, injured, elderly, or unable to care for themselves.\nBecause of this responsibility, healthcare professionals must follow strict legal and ethical\nstandards in their daily work. These standards guide how caregivers treat patients, interact with\ncoworkers, and handle sensitive information.', '/uploads/videos/1774051263685-293027530.mp4', '/uploads/materials/1774050308247-547816750.pdf', 1, 'e18758dd-35a0-4393-8be2-8216a06caad2', '2026-03-21 00:03:06.889'),
('8cf158fa-db16-47f8-8bbf-795025ced291', 'Assisting with Dressing and Hair Care', 'Assisting patients or residents with dressing is an important part of daily personal care in\nhealthcare settings. Dressing not only protects the body and keeps individuals comfortable, but\nit also helps maintain dignity, independence, and self-confidence. Many patients receiving\nhealthcare services may have limited mobility, weakness, illness, or injuries that make dressing\ndifficult. As a result, caregivers often provide partial or full assistance with this task.', '/uploads/videos/1774004926256-171311106.mp4', '/uploads/materials/1774002362667-428193752.pdf', 1, 'fdfa2362-9aa4-4527-8a6e-d7518e73afc3', '2026-03-20 11:14:33.141'),
('8d1c59f0-6f97-4def-9d64-6c269cd27f42', ' Fluid Balance, Hydration, and Intake and Output Monitoring', 'Maintaining proper fluid balance is one of the most important aspects of human health. Water\nplays a critical role in almost every physiological process in the body. It supports digestion,\nregulates body temperature, transports nutrients, removes waste products, and helps maintain\nthe normal function of organs and tissues. Because of these essential roles, healthcare\nproviders must carefully monitor fluid intake and fluid loss in residents or patients, especially\nthose who are ill, elderly, or recovering from medical procedures.', '/uploads/videos/1774053763912-801385037.mp4', '/uploads/materials/1774053477472-969192478.pdf', 1, '97f711c2-1914-40fb-905a-75fd6659c7cd', '2026-03-21 00:43:58.087'),
('8dc37f95-2c99-4214-bc2a-2911b7d87e43', 'Body Mechanics and Safety Principles for Lifting Patients', 'Assisting patients with movement and repositioning is a common responsibility for healthcare\nworkers. While helping patients move is essential for their comfort and health, it can also be\nphysically demanding for caregivers. If proper techniques are not used, caregivers may injure\nthemselves or the patient. For this reason, understanding and applying correct body\nmechanics is extremely important when lifting, turning, or repositioning patients.', '/uploads/videos/1774277005124-65175190.mp4', '/uploads/materials/1774276222350-494047821.pdf', 1, '577f8de7-22ed-4023-a5bf-7864846ff9b6', '2026-03-23 14:55:23.159'),
('8dd07bb1-a9e9-4e2b-bfa9-be8ddde760d6', ' Factors Affecting Nutrition and Dietary Planning', 'Nutrition is influenced by many biological, social, psychological, and environmental factors.\nWhile the human body requires a consistent intake of nutrients to maintain health, individuals do\nnot always consume food in the same way or under the same circumstances. A person’s age,\nculture, financial situation, health status, and personal preferences can all affect dietary habits\nand nutritional intake. In healthcare settings, especially when caring for residents or patients,\nunderstanding these factors is essential. Recognizing what influences eating behaviors allows\ncaregivers and healthcare professionals to better support individuals in meeting their nutritional\nneeds and maintaining overall well-being.', '/uploads/videos/1774052493560-525294590.mp4', '/uploads/materials/1774051735842-834656938.pdf', 1, '7f005818-5ca9-4f5a-b10b-f542c77afb48', '2026-03-21 00:21:55.948'),
('92085d3c-f008-4a16-a144-e8a6e79bebe7', 'Assisting Patients With Repositioning and Turning in Bed', 'Helping patients move and change positions in bed is one of the most common responsibilities\nin patient care. Many patients are unable to move independently because of illness, weakness,\ninjury, or medical treatment. When patients remain in one position for too long, it can lead to\ndiscomfort and serious health complications. Because of this, caregivers must regularly assist\npatients with repositioning and turning.', '/uploads/videos/1774279125393-308312455.mp4', '/uploads/materials/1774279017910-841948936.pdf', 1, 'c9685942-e2de-42cf-877d-99df4795d2c8', '2026-03-23 15:18:50.983'),
('94c262f4-1b09-4bcc-9933-3a8d85a54fa9', 'Introduction to Cleanliness and Hygiene', 'Cleanliness and hygiene refer to the practices that individuals follow to maintain their bodies\nand environments in a clean and healthy condition. These practices include bathing, brushing\nteeth, washing hands, wearing clean clothes, and keeping living spaces clean and organized.\nMaintaining cleanliness is not simply about appearance; it is primarily about protecting health\nand preventing disease.', '/uploads/videos/1773928584805-332681319.mp4', '/uploads/materials/1773928109285-297797918.pdf', 1, 'f8b50a9c-8bac-4ae7-81ea-6d98471a808a', '2026-03-19 13:56:30.107'),
('94ff8b5d-eceb-4d5c-8f4c-9452061bb0b1', 'HIPAA Course Outline, Course Outcomes, Introduction, and Overview of HIPAA', 'The Health Insurance Portability and Accountability Act, commonly known as HIPAA, plays a\ncrucial role in protecting the privacy and confidentiality of patient information in the healthcare\nenvironment. Understanding HIPAA is essential for all healthcare workers, including Certified\nNursing Assistants (CNAs), nursing aides, patient care assistants, medical assistants, and other\ndirect care staff. These professionals interact with sensitive patient information every day, and it\nis their responsibility to ensure that this information remains protected. In order to properly follow\nHIPAA guidelines, healthcare workers must understand the structure of the program, the goals\nof the training, and the responsibilities that come with handling protected health information.', '/uploads/videos/1774011821115-967277419.mp4', '/uploads/materials/1774011238908-572266396.pdf', 1, '29d7e074-4849-4512-bec2-31200432e0ee', '2026-03-20 13:05:44.896'),
('98d2f767-0ef7-4b38-8cdf-0b5d50e37fbb', 'Mechanical Lift Transfers and Final Patient Care Procedures', 'In healthcare environments, some patients are unable to assist with transfers due to weakness,\nillness, paralysis, or extreme body weight. In these situations, caregivers must use special\nequipment designed to move patients safely. One of the most important devices used for this\npurpose is the mechanical lifting device, often referred to as a mechanical lift.', '/uploads/videos/1774285716256-73443567.mp4', '/uploads/materials/1774285238307-761892731.pdf', 1, 'f2189dc8-7073-4864-96c0-2a1bd8482a41', '2026-03-23 17:08:47.597'),
('9aae3497-dae6-4628-81ab-9d5bd732041c', 'Foundations of Patient Transfer and Safety Principles', 'Transferring patients and residents is one of the most important skills required of nursing\nassistants and healthcare aides. The process involves moving a patient safely from one location\nto another, such as from a bed to a wheelchair, from a wheelchair to a chair, or from a bed to a\nstretcher. The goal of patient transfer is to ensure both the safety and comfort of the patient\nwhile also protecting healthcare workers from injury. Proper knowledge and preparation are\nessential before performing any transfer procedure.', '/uploads/videos/1774284783679-109016980.mp4', '/uploads/materials/1774284679819-241637561.pdf', 1, 'afa1ad86-c6fe-431d-b1b7-2362e8ccb815', '2026-03-23 16:53:07.769'),
('9ae73d02-a7e0-4a2a-9f80-fe4aafddcca3', 'Communication in Special and Challenging Situation', 'Effective communication requires more than simply speaking and listening. It also involves\nbeing aware of how messages are expressed through tone, body language, and emotional\nresponses. There are several additional suggestions that can help improve communication and\nmake interactions more respectful, clear, and supportive.', '/uploads/videos/1773960108379-462804451.mp4', '/uploads/materials/1773959391450-379532551.pdf', 1, 'dc2e7247-f61f-41a0-bf94-5a3ac1aeefb9', '2026-03-19 22:41:55.931'),
('a5e7a3d8-ebdf-4a53-b794-03b8e9727dfd', 'Assisting with Eyeglasses, Hearing Aids, and Finishing Up', 'Many patients and residents rely on assistive devices such as eyeglasses and hearing aids to\nhelp them see and hear clearly. These devices play an important role in maintaining\nindependence, communication, and overall quality of life. When caregivers assist with these\nitems, they must handle them carefully because they are often fragile, expensive, and essential\nfor the patient’s daily functioning.', '/uploads/videos/1774010491850-594113591.mp4', '/uploads/materials/1774009981894-524149978.pdf', 1, 'd0480a6b-2007-435b-8512-ad749cdc62b8', '2026-03-20 12:49:01.192'),
('a6e1f6ff-cc92-467e-9888-110edf3f143f', 'Conclusion and Recommendations', 'Dementia is one of the most significant health challenges affecting older adults across the world\ntoday. As populations continue to age, the number of people living with this condition is\nexpected to increase rapidly. Dementia is not a single disease but rather a syndrome that results\nfrom various underlying brain disorders that affect memory, thinking, behavior, and the ability to\nperform everyday activities. Throughout this presentation, we have explored the definition of\ndementia, its causes, symptoms, diagnosis, and management strategies. Understanding these\naspects is essential for improving early detection, providing effective care, and supporting\nindividuals and families affected by this condition.', '/uploads/videos/1773969203418-838027856.mp4', '/uploads/materials/1773968722531-305047788.pdf', 1, '05d6316e-267d-4f61-8a2f-ff0fdd88b0ad', '2026-03-20 01:13:48.574'),
('a80fb102-5c03-4aff-ad88-eb9e4ed016c4', 'What to Do When a Fall Occurs', 'Even with the best prevention strategies, falls can still happen. When a fall occurs, it is\nextremely important for caregivers and healthcare workers to respond quickly, calmly, and\ncorrectly. The actions taken immediately after a fall can make a significant difference in\npreventing further injury and ensuring the safety of the individual. For this reason, every\ncaregiver must understand the proper steps to follow when a fall happens.', '/uploads/videos/1773970838191-717179865.mp4', '/uploads/materials/1773970402130-747959653.pdf', 1, 'c77fa86c-a7ac-45b2-8235-6af9c60260e8', '2026-03-20 01:41:55.309'),
('af4484fc-8391-417c-b4d7-4495ba16c2e6', 'Introduction and Legal Aspect of Ethics', 'Ethics and legal responsibilities are extremely important in healthcare. Every healthcare\nprofessional must understand the difference between right and wrong, and they must always act\nin a way that protects the safety, dignity, and rights of patients or residents. Healthcare workers\nare placed in positions of trust, and because of this trust they must follow high ethical and legal\nstandards in their daily work', '/uploads/videos/1774048842693-656258291.mp4', '/uploads/materials/1774047807209-959132470.pdf', 1, '58ce0804-c078-41ab-9255-e9d71121b2f5', '2026-03-20 23:32:16.242'),
('b56416b0-b44e-4a25-9c85-08aed9fc10a6', 'Respiratory Assessment  Measuring and Observing Respiration', 'Respiration is one of the most essential functions of the human body because it allows oxygen\nto enter the body and carbon dioxide to be removed. Oxygen is required by every cell in the\nbody to produce energy, while carbon dioxide is a waste product that must be eliminated. The\nrespiratory system works continuously to maintain this balance. For healthcare professionals,\nmonitoring a patient’s breathing is a critical part of assessing overall health. Changes in\nbreathing patterns may indicate illness, injury, or problems affecting the lungs, heart, or nervous\nsystem. Because of this, respiration is considered one of the primary vital signs that must be\nmeasured and recorded regularly.', '/uploads/videos/1774351288349-733979205.mp4', '/uploads/materials/1774349312831-920747518.pdf', 1, '21dd94ea-8854-4cff-aea9-d3c6177996ee', '2026-03-24 11:22:37.147'),
('b5922e4f-cd40-4d74-99b4-1b98fbae8796', 'Giving a Shower or Tub Bath', 'Bathing is an essential part of personal hygiene. It helps remove sweat, dirt, bacteria, and dead\nskin cells that accumulate on the body throughout the day. Regular bathing helps maintain\nhealthy skin and prevents infections that may develop when microorganisms grow on the skin.\nFor patients in healthcare facilities, bathing is particularly important because many patients\nspend long periods in bed or have limited mobility. Without regular bathing, their skin may\nbecome irritated, dry, or infected.', '/uploads/videos/1773929897272-695316844.mp4', '/uploads/materials/1773929451108-925942811.pdf', 1, 'fcc6b2a8-5666-494c-ba16-5914668424d5', '2026-03-19 14:18:27.907'),
('b88534e3-330f-4757-885b-94f13c762cf2', 'Applying Physical Restraints Safely', 'In healthcare settings, physical restraints are sometimes required to protect patients or\nresidents from harming themselves or others. While the use of restraints is carefully regulated\nand should only be applied when absolutely necessary, healthcare workers must know how to\napply them correctly and safely when ordered by a physician. Improper use of restraints can\ncause serious physical injury, emotional distress, or even life-threatening complications. For this\nreason, healthcare workers must follow proper procedures and safety guidelines whenever\napplying physical restraints. Two of the most common types of physical restraints used in\nhealthcare facilities are vest restraints and wrist or ankle restraints.', '/uploads/videos/1774281135456-860901600.mp4', '/uploads/materials/1774280566920-831206269.pdf', 1, '510a7475-5d8f-413b-9038-5bdbc1512930', '2026-03-23 15:52:20.471'),
('b89eb4aa-8d88-4527-a394-da392310dda7', 'Fall Prevention – Introduction, Facts, and Learning Objectives', 'Falls are one of the most common and serious safety problems affecting older adults today. In\nhealthcare facilities such as nursing homes, assisted living centers, and hospitals, falls\nrepresent a major cause of injury, disability, and even death. Because of this, understanding fall\nprevention is extremely important for healthcare workers, caregivers, and anyone who works\nwith elderly individuals.', '/uploads/videos/1773969968199-195726038.mp4', '/uploads/materials/1773969498406-425732362.pdf', 1, '51872286-405e-495d-9654-58fedfdd3dca', '2026-03-20 01:26:57.661'),
('b9bcbeec-6f90-49bc-bec1-f9684108c6d4', 'Wheelchair to Bed Transfer and Bed to Stretcher Transfer', 'In healthcare settings, patients are often required to move between different types of equipment\nor surfaces depending on their medical needs. Two common procedures include transferring a\npatient from a wheelchair to a bed and transferring a patient between a bed and a stretcher.\nThese procedures are important for patient care because they allow individuals to return to bed\nfor rest, receive treatment, or be transported to other departments for diagnostic tests or\nsurgery.', '/uploads/videos/1774285182950-607110376.mp4', '/uploads/materials/1774285072613-175398017.pdf', 1, '192ead81-62e3-4a27-a816-e96fb98de32e', '2026-03-23 17:00:06.354'),
('bffcdc90-e575-4b97-987e-38ab7ce38917', 'Fundamentals of Nutrition and Essential Nutrients', 'Nutrition is one of the most fundamental components of human health. Food and water are\nessential for life, growth, healing, and maintaining normal body functions. A balanced diet\nensures that the body receives the nutrients required to sustain biological processes, maintain\nphysical and mental performance, and prevent disease. In healthcare environments, especially\nwhen caring for residents or patients, proper nutrition is vital because poor dietary habits can\nsignificantly affect recovery, immunity, and overall well-being.', '/uploads/videos/1774051683275-212374358.mp4', '/uploads/materials/1774051632524-238642127.pdf', 1, 'e86136a7-7f56-408d-af85-8f969f430a8b', '2026-03-21 00:08:16.717'),
('c01eee3d-9d74-42bf-975e-719f9d1306ef', 'Providing Perineal Care', 'Perineal care involves cleaning the genital and anal areas of the body. These areas are\nsensitive and require careful hygiene because bacteria can easily grow in warm and moist\nenvironments.\nProper perineal care helps prevent infections, skin irritation, and unpleasant odors.', '/uploads/videos/1773939677160-971189721.mp4', '/uploads/materials/1773937771494-594674930.pdf', 1, 'd8314800-15b6-4ff6-86ad-12ca574d66fa', '2026-03-19 17:21:54.153'),
('c423e2ea-96fc-476d-8a66-74cc478d125b', 'Standard Precautions and Isolation Practices in Infection Control', 'In healthcare environments, preventing the spread of infection is a critical responsibility shared\nby all members of the healthcare team. Patients in hospitals, clinics, and long-term care facilities\noften have weakened immune systems, making them more vulnerable to infectious diseases.\nFor this reason, healthcare professionals must follow strict infection control procedures. Among\nthe most important of these procedures are standard precautions and transmission-based\nprecautions, including airborne, droplet, and contact precautions. These measures are\ndesigned to protect both healthcare workers and patients from harmful microorganisms that may\nspread during care.', '/uploads/videos/1774047530555-415880449.mp4', '/uploads/materials/1774046495125-861443714.pdf', 1, 'b7cb43f4-3dca-41bf-8e14-fe5dc9a53191', '2026-03-20 23:01:33.489'),
('c7995fdf-24de-48c4-99cd-092de464347a', 'Introduction and Course Overview', '', '/uploads/videos/1773923609172-532560714.mp4', '/uploads/materials/1773922991620-667012175.pdf', 1, '4eb4869b-acb6-42c3-8222-62459c23af46', '2026-03-19 12:33:46.594'),
('c8fe9d20-6e0f-4bab-98ab-60e352387a09', ' Meal Assistance, Feeding Practices, and Monitoring Nutritional Status', '', '/uploads/videos/1774053935827-184851507.mp4', '/uploads/materials/1774053883226-179920897.pdf', 1, 'b158910f-5718-4082-a42f-f746517fbe56', '2026-03-21 00:45:51.436'),
('c91f495f-605f-42a2-ad40-f508d55edbed', 'Observation, Reporting, and Communication Barriers', 'When nursing assistants report information about residents, it is very important that the\ninformation is accurate, clear, and factual. Healthcare professionals depend on the information\nthey receive from nursing assistants to make important decisions about treatment and care.\nBecause of this, nursing assistants must understand the different kinds of information they are\nexpected to report. Two main types of information are commonly used in healthcare reporting:\nobjective information and subjective information.', '/uploads/videos/1773959317850-41191860.mp4', '/uploads/materials/1773958631181-628977353.pdf', 1, 'd1727436-e227-4c9f-9dec-f4fe51f7f6d0', '2026-03-19 22:28:46.465'),
('cc8f1da4-cf69-4c17-a598-bf0904b2cab5', 'Ways to Treat the Dying Resident and Their Families with Dignity', 'Providing care for a dying resident involves more than managing physical symptoms. It also\nrequires maintaining the dignity, respect, and emotional well-being of both the resident and\ntheir family. The final stage of life is deeply emotional, and the way healthcare workers behave\nduring this time can have a lasting impact on the patient and their loved ones.\nDignity in healthcare means recognizing the inherent value of every person. Even when\nsomeone is weak, unconscious, or close to death, they deserve to be treated with the same\nrespect as any other individual. Healthcare professionals must demonstrate compassion,\nprofessionalism, and sensitivity in every interaction with the dying resident and their family\nmembers.', '/uploads/videos/1773965443157-810643706.mp4', '/uploads/materials/1773964878985-762743823.pdf', 1, '4f6295c5-0856-4d97-9f3d-c1b673607238', '2026-03-20 00:11:32.589'),
('cf32fe0c-81af-45bb-906b-5ef6e2bcb3ed', 'How to Manage Difficult Behaviors', 'Managing difficult behaviors in people with dementia is one of the most important\nresponsibilities for caregivers and healthcare workers. As dementia progresses, individuals\noften lose the ability to communicate their needs clearly. Because of this, behaviors such as\nagitation, wandering, or repetition may occur. These behaviors can sometimes be challenging or\nfrustrating, but they should always be understood as a form of communication rather than\nintentional misbehavior.', '/uploads/videos/1773968144956-635434255.mp4', '/uploads/materials/1773967667480-885614617.pdf', 1, 'c5ce8b93-6f26-4240-924d-a87a9b63b021', '2026-03-20 00:55:59.742'),
('e247f865-67fc-4626-ab55-ad9d8402154b', 'Special Diets and Therapeutic Nutrition Management', 'In healthcare settings, many residents cannot follow a regular diet due to medical conditions,\nrecovery from illness, or difficulty eating normally. For this reason, healthcare providers often\nprescribe special or therapeutic diets. These diets are carefully designed meal plans that help\nmanage specific health conditions, improve recovery, prevent complications, and support overall\nwell-being. Therapeutic diets modify the amount, texture, or timing of foods and nutrients to\nmeet the medical needs of each individual.', '/uploads/videos/1774053404165-852752653.mp4', '/uploads/materials/1774052558783-903140152.pdf', 1, 'bcdd9990-da46-46b5-8513-3d023b3e12a9', '2026-03-21 00:36:48.960');
INSERT INTO `Lesson` (`id`, `title`, `description`, `videoUrl`, `materialUrl`, `order`, `moduleId`, `createdAt`) VALUES
('e4d98515-a30d-4028-8e73-f98036292342', 'Guidelines for Stress Management', 'Stress is a natural part of life, but learning how to manage it effectively is essential for\nmaintaining both mental and physical well-being. Stress management refers to the techniques,\nhabits, and strategies people use to reduce the negative effects of stress and maintain balance\nin their daily lives. In demanding professions such as healthcare, stress management becomes\neven more important because workers must remain focused, patient, and emotionally stable\nwhile caring for others. By developing healthy routines and practical strategies, individuals can\nreduce stress and improve their overall quality of life.', '/uploads/videos/1774284434861-776302959.mp4', '/uploads/materials/1774284364058-903328327.pdf', 1, '48056cc0-92f5-4ea8-908a-dd07a00b458c', '2026-03-23 16:47:18.383'),
('e532c232-535e-44b8-8492-b515adbd938c', 'Bed to Wheelchair Transfer Procedure', 'One of the most common transfers performed in healthcare settings is moving a patient from a\nbed to a wheelchair. This transfer allows patients to leave the bed for activities such as meals,\ntherapy sessions, examinations, or social interaction. Although this procedure is routine, it must\nbe performed carefully to ensure the safety and comfort of the patient while protecting the\ncaregiver from injury.', '/uploads/videos/1774285038573-264981007.mp4', '/uploads/materials/1774284955092-358269577.pdf', 1, '9b2d4993-45f3-4576-beb4-eb01bd0bac63', '2026-03-23 16:57:23.742'),
('e84f5591-a442-44b6-a0e7-d9dea5fad8ac', 'Preparation', 'Preparation is the foundation of safe and professional elimination care. Before assisting a\nresident with any urinary or bowel procedure, proper preparation ensures safety, infection\ncontrol, efficiency, and preservation of dignity.', '/uploads/videos/1773924145198-204875983.mp4', '/uploads/materials/1773923699630-950200059.pdf', 2, '4eb4869b-acb6-42c3-8222-62459c23af46', '2026-03-19 12:42:54.823'),
('e96d5beb-dd3b-4325-a5c2-11ee7d834ab2', 'Proper Communication and Resident Interaction', 'Proper communication is an essential part of providing quality care and building respectful\nrelationships with residents. Communication should always be professional, respectful, and\nfocused on the needs of the resident. When communicating with a resident, it is important to\ntreat them with dignity and respect at all times. One of the most important steps in proper\ncommunication is addressing the resident by his or her preferred name. Using the correct\nname helps the resident feel respected and recognized as an individual.', '/uploads/videos/1773958531742-964786859.mp4', '/uploads/materials/1773957609147-138487085.pdf', 1, '56ea02ae-0e9d-4523-bb17-0e39fcc28842', '2026-03-19 22:16:03.278'),
('ee10e19e-2826-4e86-a364-cff54e62a2b9', 'Legal Rights and Preferences of a Terminally Ill Resident', 'When a person is approaching the end of life, healthcare providers must not only focus on\nphysical care and comfort but also respect the legal rights and personal wishes of the patient.\nTerminally ill residents remain individuals with full legal and human rights, even as their health\ndeclines. Respecting these rights ensures that patients maintain dignity, autonomy, and control\nover important decisions about their care.\nHealthcare professionals—including nurses, caregivers, and nursing assistants—must\nunderstand these rights because they guide how care should be provided. These rights protect\nthe patient’s ability to make decisions about their body, their treatment, their privacy, and the\nway they wish to spend their final days.\nUnderstanding and respecting these legal and ethical principles is an essential part of\nprofessional healthcare practice.', '/uploads/videos/1773964798437-114734740.mp4', '/uploads/materials/1773964314713-193073698.pdf', 1, 'd6e9e9b7-44fb-4fe2-ac80-fe6cbcca6e7e', '2026-03-20 00:00:21.182'),
('ef8f4407-519f-4c1b-ab59-985eaa904ba6', 'Common Behaviors in People with Dementia', 'People who are living with dementia often display behaviors that may seem unusual, confusing,\nor difficult for caregivers to understand. These behaviors are not intentional. They occur\nbecause the brain changes caused by dementia affect memory, judgment, communication, and\nemotional control. As the disease progresses, individuals lose the ability to interpret their\nenvironment accurately or communicate their needs clearly. As a result, behaviors become one\nof the main ways they express discomfort, confusion, fear, or unmet needs.', '/uploads/videos/1773967573902-621167709.mp4', '/uploads/materials/1773967058340-650332736.pdf', 1, '7ebf3e29-a34c-4946-9d3f-5d28fe5ae663', '2026-03-20 00:46:58.849'),
('f038bc38-0e9b-4d4b-8dc7-b848b2b9597e', 'Shaving a Man’s Face and Assisting with Care of Hands and Feet', 'Shaving is an important part of personal grooming for many male patients and residents.\nMaintaining facial hair hygiene helps individuals feel clean, comfortable, and confident in their\nappearance. For patients who are unable to shave independently due to illness, weakness, or\nlimited mobility, caregivers may assist with this task. However, shaving requires careful attention\nto safety and hygiene to avoid injury and infection.', '/uploads/videos/1774007235277-710305093.mp4', '/uploads/materials/1774005447928-387762897.pdf', 1, 'fa4e7ac6-8591-45e6-88bf-50a5c2f9bce5', '2026-03-20 11:56:43.777'),
('f0d340b3-1f95-4c19-8c39-0bbaf4ecbb51', 'Medical Asepsis and Barrier Methods', 'Infection control in healthcare settings relies heavily on practical daily actions that prevent\nharmful microorganisms from spreading. Two of the most important components of these\npractices are medical asepsis and barrier methods. These techniques are used constantly by\nhealthcare workers and form the foundation of safe patient care. By understanding and correctly\napplying these methods, healthcare workers can significantly reduce the risk of infections for\nthemselves and the people they care for.', '/uploads/videos/1774046428265-725307174.mp4', '/uploads/materials/1774045634516-159830759.pdf', 1, '11b6263a-2493-4abd-b4ea-cfb20fd6f3d3', '2026-03-20 22:40:40.179'),
('f288a730-a281-423e-9eec-ca504d91a6d0', 'Common Signs of Approaching Death', 'As a person approaches the end of life, the body gradually begins to shut down. This process\ndoes not usually happen suddenly; instead, it occurs slowly as different body systems begin to\nweaken and stop functioning. Recognizing the signs that death may be approaching is important\nfor caregivers, nurses, and healthcare assistants. Understanding these signs allows caregivers\nto provide appropriate comfort care and helps them prepare the patient’s family for what may\nhappen.', '/uploads/videos/1773963540567-149006705.mp4', '/uploads/materials/1773962921832-868038066.pdf', 1, '8279b761-8df3-4c85-9a50-9c1b2f3d3c7b', '2026-03-19 23:40:30.955'),
('f37012c1-08ff-4c92-9725-d6c90ae228f5', 'Common Confidentiality Violations, Patient Privacy Rights, and Protection of Confidential Information', 'Protecting patient confidentiality is one of the most important responsibilities of healthcare\nprofessionals. While HIPAA establishes rules designed to safeguard protected health\ninformation, violations of confidentiality can still occur in many healthcare environments. In\nmany cases, these violations are not intentional but occur because staff members are not fully\naware of how easily sensitive information can be exposed. Understanding the most common\nways that confidentiality is violated can help healthcare professionals avoid mistakes and\nmaintain compliance with privacy regulations.', '/uploads/videos/1774036521437-328763795.mp4', '/uploads/materials/1774034822624-392485055.pdf', 1, '39886348-6c90-47ec-992d-b37c4a9e6083', '2026-03-20 19:55:33.217'),
('f45a5c0f-27ab-443b-a7d7-cc38245c8ddb', 'Who Must Comply with HIPAA, Key HIPAA Rules for CNAs, and Important Privacy Concepts', 'HIPAA compliance applies to a wide range of individuals and organizations within the healthcare\nindustry. Any person or organization that works with health information or has access to\nprotected health information must follow HIPAA regulations. This requirement ensures that\npatient information remains protected regardless of where it is stored, processed, or shared.\nThe responsibility for maintaining patient confidentiality does not belong only to doctors and\nnurses; it extends to everyone involved in healthcare services or administrative operations.', '/uploads/videos/1774013393254-868452284.mp4', '/uploads/materials/1774012222569-736493808.pdf', 1, '218a2acc-3b61-4c95-9930-45950c1448d9', '2026-03-20 13:34:14.316'),
('f54bb8ae-5300-4d67-8223-c146ce5b4fdd', 'The Chain of Infection, Why Infections Spread Easily, and Microbes & Communicable Infections', 'Understanding infection control requires more than simply knowing that germs exist. Healthcare\nworkers must understand how infections actually spread. One of the most important concepts\nin infection control is called the chain of infection. This concept explains the process through\nwhich an infection moves from one person to another. By understanding this chain, healthcare\nworkers can identify ways to interrupt it and prevent the spread of disease.', '/uploads/videos/1774040406964-548975654.mp4', '/uploads/materials/1774038381397-630522916.pdf', 1, 'd3f1e51b-cccb-40d7-91c8-ef92b9ffe04f', '2026-03-20 21:00:20.592');
