INSERT INTO `Question` (`id`, `text`, `options`, `correctAnswer`, `quizId`) VALUES
('0056f46d-0718-43d2-abc9-3b86bf0b196d', 'During the lift, the patient should be…', '[\"Left unattended\",\"Moved quickly\",\"Reassured and monitored for comfort and safety\",\"Ignored\"]', 2, '20efff82-6d52-4bd6-b13a-21418d0239af'),
('009557d2-fabc-4871-a696-6c32feca7310', 'What is the main purpose of maintaining professional behavior when caring for a dying resident?', '[\"To complete tasks faster\",\"To avoid interacting with the family\",\"To ensure respect, calmness, and focus on the resident’s needs at all times\",\"To reduce communication with staff\"]', 2, '370385a0-ca51-46e4-b084-cb74b5ee74b8'),
('0128f6ef-7624-4099-ab7f-799760e6ba4c', 'You can share information about a person\'s care and condition with...', '[\"The staff caring for the person\",\"The family members\",\"The person\'s daughter\",\"The volunteer in the gift shop\"]', 0, '11ac83d9-baf5-43d1-a21f-17db499df927'),
('01763653-c5d0-4ab1-ab85-724bc6cdb413', 'What is the purpose of a lift sheet in a bed-to-stretcher transfer?', '[\"To decorate the bed\",\"To provide a secure way to lift and move the patient safely\",\"To reduce communication\",\"To increase workload\"]', 1, 'c6b12a96-0b96-4817-8611-cfce3e324573'),
('021ce69a-4ab1-4fda-9459-2b6603c32110', 'What does systolic blood pressure represent?', '[\"Pressure when the heart relaxes\",\"Pressure in veins\",\"Pressure when the heart contracts and pushes blood ou\",\"Pressure during sleep\"]', 2, '9efcfbe0-4ab4-4f1d-8a4b-5dde1a3a3af4'),
('02a4f580-51e5-49e8-8159-ba01b27ca2ec', 'How does the condition of frailty specifically impact an older adult\'s physical capabilities in the context of fall prevention?', '[\"It results in a body that is less able to handle stress, characterized by reduced strength and difficulty maintaining balance\",\"It refers specifically to a person\'s inability to see uneven surfaces\",\"It is a temporary state caused only by taking blood-thinning medications\",\"It describes an older adult who refuses to use community exercise resources\"]', 0, '3cf47254-a409-400d-80c9-02d44010d074'),
('02c102a5-74ad-4e29-a972-863ed0491331', 'Why are employer-sponsored health plans required to comply with HIPAA regulations?', '[\"Because they collect and manage health-related information about employees\",\"To help employers decide which employees to promote\",\"To ensure all employees use the same insurance company\",\"To allow managers to see employee medical history for any reason\"]', 0, '59822924-bebe-4ed4-90f2-54a28febdb0b'),
('043f9161-72fc-40ce-9ee8-fd24ac313d4a', 'Why is compassionate presence important in end-of-life care?', '[\"It replaces medical treatment\",\"It helps residents and families feel supported and less alone\",\"It allows caregivers to avoid communication\",\"It shortens the dying process\"]', 1, '370385a0-ca51-46e4-b084-cb74b5ee74b8'),
('04560d81-137b-44f4-b752-18c98e1b636c', 'How should a restraint fit on a patient?', '[\"Very tight\",\"Loose and falling off\",\"Snug with space for fingers or a hand to fit between restraint and body\",\"Extremely tight around joints\"]', 2, 'deaf63e7-7806-44f2-92cb-75c1f5c542c5'),
('055d7cfe-9954-4072-ac6d-58e10b7c357f', 'Why do terminally ill residents have the right to refuse treatment?', '[\"Because treatment is always ineffective\",\"Because of patient autonomy and control over their own body and care decisions\",\"To reduce hospital costs\",\"To make work easier for caregivers\"]', 1, 'a96de350-39f0-44e1-84ac-cbfcaa55cd35'),
('0646c8ea-658e-4a55-9565-4c2e12183416', 'Faulty electrical equipment…', '[\"Can be used in a nursing station\",\"Should be given to the nurse\",\"Should be taken home for repair\",\"Should only be used by alert persons\"]', 1, 'f11f8615-5686-41c1-a549-34a649f9c6a4'),
('06c9bbfc-7e88-4e44-bf40-3798c9c2e3e2', 'When transferring a patient with a mechanical lift, how many caregivers are usually required for safety?', '[\"One caregiver\",\"Two caregivers\",\"Three caregivers\",\"No caregiver\"]', 1, '20efff82-6d52-4bd6-b13a-21418d0239af'),
('0983e898-c28c-4522-9e74-050cdadefb09', 'Most falls occur in:', '[\"Resident rooms and bathrooms\",\"Dining rooms\",\"Hallways\",\"Activity rooms\"]', 0, '2d454161-7461-4f34-bb59-00c45483349b'),
('0a439714-3307-4dd0-a727-e7e89024bb4a', 'Why should caregivers encourage patient independence during hygiene care?', '[\"To reduce workload only\",\"To save supplies\",\"To improve the patient’s self-esteem and sense of control\",\"To shorten care time\"]', 2, 'f8710db2-d98a-4e70-aac6-6620637b7333'),
('0a5e3dd5-145a-43cf-a851-d29c24ae1c71', 'Which specific HIPAA component establishes the national standards for how protected health information may be used and disclosed?', '[\"The Security Rule\",\"The Privacy Rule\",\"The Portability Act\",\"The Accountability Clause\"]', 1, 'c20a5ab2-bfbd-4e3c-b4ee-1be19491e8e2'),
('0ab4f7f0-43af-44a8-af38-c4ab4430c6a8', 'Why is a low-protein diet recommended for some kidney disease patients?', '[\"To increase muscle mass\",\"To reduce waste buildup that kidneys must filter\",\"To improve carbohydrate digestion\",\"To eliminate fat intake\"]', 1, '4fa74711-53a5-4985-b2e6-d5cf499b13bd'),
('0b15f76b-9137-4c89-91b7-358f32ebcf4c', 'What is the appropriate action if a patient is praying when you enter the room?', '[\"Interrupt them\",\"Continue talking loudly\",\"Quietly leave and allow them privacy\",\"Turn on the lights\"]', 2, 'f05a82d8-65a9-487f-a881-7c6b69520dd7'),
('0bf5aaec-9935-4e5f-8a4c-2e0717b6ba7c', 'Which of the following represents a patient\'s specific right regarding their own Protected Health Information (PHI)?', '[\"The right to delete any part of their medical history permanently\",\"The right to request a copy of their records and ask for corrections\",\"The right to see the medical records of their roommates\",\"The right to share their doctor\'s personal home address\"]', 1, '9f75fc6c-78f9-4c29-969d-925e784bbe4c'),
('0c329bdd-bc66-4a4f-a003-1d7e01b82e94', 'What is the correct angle to hold a toothbrush when brushing teeth?', '[\"90-degree angle to the teeth\",\"30-degree angle away from gums\",\"45-degree angle to the gums\",\"Flat against the teeth\"]', 2, '8c43867b-df17-4281-8327-5afd858ce2cb'),
('0c3db612-9c6d-487e-930a-de3bafca0314', 'What information should be given when calling for emergency help?', '[\"Only the patient’s name\",\"No information\",\"Clear details about condition, location, and events\",\"Personal opinions\"]', 2, '397caf60-5dc5-4b5c-b4b6-48f2bd6886b3'),
('0c8f1fca-5622-43e4-a530-0b1cb8934dc6', 'Which situation would make rectal temperature measurement unsafe for a patient?', '[\"Patient is cooperative\",\"Patient has hemorrhoids or rectal bleeding\",\"Patient is calm\",\"Patient is awake\"]', 1, 'e3935e28-e1fd-48fd-964f-d1b5be8d3daa'),
('0c8fcb7a-67fb-4e37-87a5-40ea90025e86', 'What should a caregiver do before starting the transfer procedure?', '[\"Ignore the patient\",\"Move quickly\",\"Explain the procedure to the patient\",\"Turn off lights\"]', 2, '2556291b-0982-48da-beaa-944ee7120230'),
('0d0f7d54-a657-4955-9cc5-e0c86692f798', 'What is the Sims’ position commonly used for?', '[\"Feeding\",\"Walking\",\"Rectal procedures like enemas\",\"Sleeping upright\"]', 2, '389a7d8d-2938-4604-8d2f-84f846d84e5a'),
('0e0b7da5-02e6-41e2-bc32-8bd78bbd1b9d', 'None of the following should be used in a code of ethics, except:', '[\"Social norms\",\"Personal feelings\",\"Religious doctrine\",\"Professionally mandated standards\"]', 3, '901e5737-19aa-41c8-a13a-cc963b5f734c'),
('0e231859-4de0-46fd-aa1d-563b819621c8', 'How can unmanaged stress affect a caregiver’s behavior toward patients?', '[\"They become more patient\",\"They may show anger or irritability\",\"They always stay calm\",\"They ignore all tasks\"]', 1, '218f2d05-39ac-44dd-99dd-fc13199f5e2c'),
('0e9faf0b-f173-436a-84cb-58429a445cd4', 'Which of the following is a characteristic of water-soluble vitamins?', '[\"They are stored in large amounts in the body\",\"They are only found in animal products\",\"They must be consumed regularly because they are not stored significantly\",\"They are only needed once a week\"]', 2, '830b371f-b69f-41b9-9d04-bee30bc9ba6f'),
('0f8a6072-bc1e-431e-b600-860f793b6672', 'A person with Alzheimer’s disease likes to wander. You should…', '[\"Keep the person in his or her room.\",\"Restrain the person as much as possible.\",\"Argue with him or her.\",\"Exercise the person as ordered.\"]', 3, '208abab1-1f76-4904-bc79-331e30d79ecc'),
('102c84fb-fdef-42ba-9dea-4edb0880e254', 'What should a caregiver do immediately after identifying the patient and before starting any grooming task?', '[\"Leave the room to find more supplies\",\"Explain the procedure to the patient to ensure they understand what is happening\",\"Lower all side rails regardless of the care plan\",\"Put on a gown and mask for every procedure\"]', 1, 'b408ceab-70e7-4415-8bc8-a44e1d40137f'),
('10816207-96b7-4c38-b951-f3f7de8862dd', 'Why is honesty important in healthcare?', '[\"It helps workers avoid responsibility\",\"It builds trust between patients and caregivers\",\"It reduces the need for documentation\",\"It allows staff to ignore mistakes\"]', 1, '22ce5fde-f7e9-4180-b8a7-e490c6d72822'),
